// @concept: trust-proxy
export function trustProxyHops(hops: number): TrustProxy {
  // 1. 0 hops (local dev, Docker, CI): trust nobody. request.ip is whoever connected to us.
  if (hops === 0) return false;

  // 2. N hops: trust the N nearest addresses, whatever they are, EXCEPT when the connection itself
  //    (hop 0) comes from localhost: that is a Service Connect call, with no proxies of ours in
  //    front (see above). Saying "not trusted" at hop 0 makes Fastify stop right there.
  return (address, hop) => hop < hops && !(hop === 0 && LOCALHOST.has(address));
}

// @concept: connection-pooling
// 1. A Pool keeps a small set of open database connections and reuses them.
//    Opening a connection is slow (network + login), so we do it a few times
//    and share them, instead of once per request.
//    `max` is the most connections open at once. If all are busy, extra queries
//    wait in line. Postgres itself allows only ~100 connections in total, so
//    we keep our share small and explicit.
//    env.database is either { connectionString } (local) or host, user, password + SSL (AWS).
export const pool = new Pool({
  ...env.database,
  max: 10,
  // P10. Bound pool acquisition/connect and SQL work, including row-lock waits.
  connectionTimeoutMillis: 2000,
  statement_timeout: 5000,
});

// @concept: fail-fast
// 2. If the database restarts or stops, idle connections in the pool break and the pool
//    emits an "error" event. Node crashes the whole process when an "error" event has no
//    listener, so we log it instead. The pool drops the dead connection and opens a new
//    one on the next query, so the API recovers by itself when the database returns.
pool.on("error", (err) => {
  console.error("Idle database connection failed:", err.message);
});

// @concept: drizzle-schema
// 3. The Drizzle instance wraps the pool. Queries use `db`; shutdown closes `pool`.
export const db = drizzle(pool, { schema: { ...users, ...events, ...bookings, ...outbox } });

// @concept: drizzle-schema
// 3. The Drizzle instance wraps the pool. Queries use `db`; shutdown closes `pool`.
export const db = drizzle(pool, { schema: { ...users, ...events, ...bookings, ...outbox } });

// @concept: migrations
// Applies the SQL files in ./drizzle to the database, then exits.
// In Docker it runs as a separate one-off container (`node dist/migrate.js`), NOT inside
// the API: with several API containers starting together, they would all migrate at once.
// On AWS it runs as a one-off ECS task (scripts/run-migrations.sh).
// It is NOT built on drizzle-kit, because drizzle-kit is a dev tool that is not in the production image.

// 1. This script needs only the database settings, so it validates only those
//    (config/env.ts would also demand PORT, REDIS_URL, ... which a migration does not use).
//    Same rules as the API: DATABASE_URL locally, or DB_* with SSL on AWS.
const result = DatabaseEnvSchema.safeParse(process.env);
if (!result.success) {
  console.error("Invalid database settings:", z.flattenError(result.error).formErrors);
  process.exit(1);
}

try {
  // @concept: idempotency
  // 3. Run every migration that has not run yet. Drizzle remembers the finished ones in the
  //    database, so running this twice is safe. The folder path is relative to the working directory (/app).
  await migrate(drizzle(pool), { migrationsFolder: "./drizzle" });
  console.log("migrations applied");
} catch (err) {
  // 4. Exit with a non-zero code so Docker Compose knows the migration failed.
  console.error("migration failed:", err);
  process.exitCode = 1;
} finally {
  // 5. Close the connection, otherwise Node would wait for it and never exit.
  await pool.end();
}

