// @concept: web-vitals
function report(metric: { name: string; value: number; id: string; rating: string }) {
  // 1. Strip ids/query strings before sending, so private URLs never enter telemetry logs.
  const path = window.location.pathname;
  const route = /^\/events\/[^/]+$/.test(path) ? "/events/[id]" : path;
  const parsed = WebVitalInput.safeParse({ name: metric.name, value: metric.value, id: metric.id,
    rating: metric.rating, route: WebVitalInput.shape.route.safeParse(route).success ? route : "/other" });
  if (!parsed.success) return;
  // 2. Keep a stable callback and use keepalive for navigation/unload. No cookies, retries or user ids.
  void fetch(`${process.env.NEXT_PUBLIC_API_URL ?? ""}/trpc/telemetry.report`, {
    method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(parsed.data),
    credentials: "omit", keepalive: true,
  }).then(response => {
    // 3. Drain the small acknowledgement: an unread keepalive body can leave Chromium's request open.
    return response.text();
  }).catch(() => {});

//    style elements require a nonce in production. Dev additionally needs eval/HMR connections.
// @concept: csp
export function securityPolicy(nonce: string, dev: boolean, apiOrigin = "") {
  const api = apiOrigin ? new URL(apiOrigin).origin : "";
  const s3 = "https://*.s3.amazonaws.com https://*.s3.us-east-1.amazonaws.com";
  return [
    "default-src 'self'", `script-src 'self' 'nonce-${nonce}' 'strict-dynamic'${dev ? " 'unsafe-eval'" : ""}`,
    `style-src 'self' ${dev ? "'unsafe-inline'" : `'nonce-${nonce}'`}`, "style-src-attr 'unsafe-inline'",
    `connect-src 'self' ${api} ${s3}${dev ? " http://localhost:* http://127.0.0.1:* ws://localhost:* ws://127.0.0.1:*" : ""}`,
    `img-src 'self' data: blob: ${s3}${dev ? " http://localhost:* http://127.0.0.1:*" : ""}`,
    "font-src 'self'", "object-src 'none'", "base-uri 'self'", "form-action 'self'", "frame-ancestors 'none'",
  ].join("; ");
}

